<?php
declare(strict_types=1);
require_once __DIR__.'/Folders.php';
return new class implements DirectWeb\Plugins\Plugin {
    public function register(DirectWeb\Core\App $app,DirectWeb\Plugins\Registry $registry): void
    {
        $folders=new DirectWebFolders\Folders($app);$registry->routes['folders']=$folders;
        $registry->addPage('folders','Folders','folder',function(array $u)use($app,$folders){
            $app->auth->requireOwner($u);$p=new DirectWeb\Ui\Surface($app,'Folders','plugin.folders',$u);$items=[];foreach($folders->roots() as $root){$link=$p->link($root['name'],'/admin/folder?root='.$root['id'],'folder');$link['label']=$root['name'];$items[]=$link;}$p->section('Folders',$items?:[$p->text('No items yet.')],['directory'=>true,'icon'=>'folder']);$p->section('Add folder',[$p->form('folders.add','',['name'=>['label'=>'Name','required'=>true],'path'=>['label'=>'Server path','required'=>true]],[],'Add')],['icon'=>'plus']);$p->section('Server',[$p->text('Apache 2.4 and AllowOverride permissions are required.'),$p->text('These rules apply to physical folders served by the webserver.')],['icon'=>'server']);return $p->build();
        },['roles'=>['owner'],'group'=>'system']);
        $registry->pages['folder']=function(array $u)use($app,$folders){
            $app->auth->requireOwner($u);$root=(string)($_GET['root']??'');$path=(string)($_GET['path']??'');$directory=$folders->directory($root,$path);$p=new DirectWeb\Ui\Surface($app,'Folder','plugin.folder.'.substr(hash('sha256',$root.'|'.$path),0,16),$u);$p->section('Location',[$p->text($directory,false),$p->link('Folders','/admin/folders','folder')],['icon'=>'folder']);$rows=[];foreach(new FilesystemIterator($directory) as $entry){if(count($rows)>=200){break;}if($entry->isDir()&&!$entry->isLink()&&!str_starts_with($entry->getFilename(),'.')){$relative=($path!==''?$path.'/':'').$entry->getFilename();$rows[]=['name'=>['label'=>$entry->getFilename(),'href'=>'/admin/folder?'.http_build_query(['root'=>$root,'path'=>$relative])]];}}if($rows){$p->section('Subfolders',[$p->table('Folders',['name'=>'Name'],$rows)],['icon'=>'folder']);}
            $saved=$app->db->one('SELECT options FROM folder_rules WHERE root=? AND path=?',[$root,$path]);$options=$saved?json_decode($saved['options'],true):['listing'=>'inherit','access'=>'inherit','ips'=>''];$p->section('Rules',[$p->form('folders.preview','',['listing'=>['label'=>'Directory listing','kind'=>'choice','value'=>$options['listing'],'options'=>[['value'=>'inherit','label'=>'Inherit'],['value'=>'off','label'=>'Off'],['value'=>'on','label'=>'On']]],'access'=>['label'=>'Access','kind'=>'choice','value'=>$options['access'],'options'=>[['value'=>'inherit','label'=>'Inherit'],['value'=>'blocked','label'=>'Blocked'],['value'=>'ip','label'=>'Selected IP addresses']]],'ips'=>['label'=>'IP addresses','value'=>$options['ips']],'index'=>['label'=>'Index files','value'=>$options['index']??''],'error_403'=>['label'=>'403 page','value'=>$options['error_403']??''],'error_404'=>['label'=>'404 page','value'=>$options['error_404']??''],'error_500'=>['label'=>'500 page','value'=>$options['error_500']??''],'cache'=>['label'=>'Cache','kind'=>'choice','value'=>$options['cache']??'inherit','options'=>array_map(fn($v)=>['value'=>$v,'label'=>ucfirst($v)],['inherit','off','hour','day','week'])],'protect'=>['label'=>'Password protection','kind'=>'checkBox','value'=>$options['protect']??false],'username'=>['label'=>'Username','value'=>$options['username']??''],'password'=>['label'=>'Password','kind'=>'passwordField']],['root'=>$root,'path'=>$path],'Preview')],['icon'=>'shield-halved']);
            $changes=$app->db->all('SELECT id,created_at FROM folder_changes WHERE root=? AND path=? ORDER BY created_at DESC,rowid DESC LIMIT 30',[$root,$path]);if($changes){$p->section('Versions',[$p->form('folders.restore','',['change'=>['label'=>'Version','kind'=>'choice','value'=>$changes[0]['id'],'options'=>array_map(fn($v)=>['value'=>$v['id'],'label'=>$v['created_at'],'literal'=>true],$changes)]],['root'=>$root,'path'=>$path],'Restore',true)],['icon'=>'arrow-rotate-left']);}return $p->build();
        };
        $registry->pages['folder-preview']=function(array $u)use($app){
            $app->auth->requireOwner($u);$id=(string)($_GET['preview']??'');$entry=$_SESSION['folder_previews'][$id]??null;if(!$entry||$entry['expires']<time()||$entry['user']!==$u['id']){throw new DirectWeb\Core\Problem('Preview expired.',410);}$view=$entry['value'];$p=new DirectWeb\Ui\Surface($app,'Preview','plugin.folder.preview.'.substr(hash('sha256',$id),0,16),$u);$p->section('Folder',[$p->text($view['directory'],false)],['icon'=>'folder']);$p->section('Current',[$p->node('codeBlock',['text'=>$view['before']['text']])],['icon'=>'code']);$p->section('New',[$p->node('codeBlock',['text'=>$view['after']]),$p->form('folders.apply','',[],['preview'=>$id],'Apply',true),$p->link('Cancel','/admin/folder?'.http_build_query(['root'=>$view['root'],'path'=>$view['path']]),'arrow-rotate-left')],['icon'=>'code']);return $p->build();
        };
        $registry->addAction('folders.add',function(array $u,array $i)use($folders){$folders->add($u,(string)($i['name']??''),(string)($i['path']??''));return '/admin/folders';});
        $registry->addAction('folders.preview',function(array $u,array $i)use($folders){$view=$folders->preview($u,$i);$id=DirectWeb\Core\Files::id();$_SESSION['folder_previews']??=[];foreach($_SESSION['folder_previews'] as $key=>$entry){if($entry['expires']<time()){unset($_SESSION['folder_previews'][$key]);}}if(count($_SESSION['folder_previews'])>=5){array_shift($_SESSION['folder_previews']);}$_SESSION['folder_previews'][$id]=['value'=>$view,'user'=>$u['id'],'expires'=>time()+600];return '/admin/folder-preview?preview='.$id;});
        $registry->addAction('folders.apply',function(array $u,array $i)use($folders){$id=(string)($i['preview']??'');$entry=$_SESSION['folder_previews'][$id]??null;if(!$entry||$entry['expires']<time()||$entry['user']!==$u['id']){throw new DirectWeb\Core\Problem('Preview expired.',410);}$view=$entry['value'];$folders->apply($u,$view);unset($_SESSION['folder_previews'][$id]);return '/admin/folder?'.http_build_query(['root'=>$view['root'],'path'=>$view['path']]);});
        $registry->addAction('folders.restore',function(array $u,array $i)use($folders){$folders->restore($u,(string)($i['change']??''));return '/admin/folder?'.http_build_query(['root'=>(string)($i['root']??''),'path'=>(string)($i['path']??'')]);});
    }
};
